def f(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    g=[r[:] for r in g]
    from collections import defaultdict
    byc=defaultdict(list)
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg: byc[g[r][c]].append((r,c))
    for col,pts in byc.items():
        pset=set(pts)
