def f(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    g=[r[:] for r in g]
    from collections import defaultdict
    # group by color and diagonal line
    for dr,dc in ((1,1),(1,-1)):
        lines=defaultdict(list)
        for r in range(h):
            for c in range(w):
                if g[r][c]!=bg:
                    lines[(g[r][c], (r-c) if dr==1 else (r+c))].append((r,c))
        for (col,key),pts in lines.items():
            pts.sort()
            # split into consecutive segments
            segs=[]; cur=[pts[0]]
            for p in pts[1:]:
                if p[0]==cur[-1][0]+dr and p[1]==cur[-1][1]+dc: cur.append(p)
                else: segs.append(cur); cur=[p]
            segs.append(cur)
            for seg in segs:
                if len(seg)<2: continue
                if any(r==0 or r==h-1 or c==0 or c==w-1 for r,c in seg): continue
                # extend both ends
                r,c=seg[0]; rr,cc=r-dr,c-dc
                while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
                    g[rr][cc]=col; rr-=dr; cc-=dc
                r,c=seg[-1]; rr,cc=r+dr,c+dc
                while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
                    g[rr][cc]=col; rr+=dr; cc+=dc
    return g
